const hasConfiguredOperatorsForRole = (
  roleName: string,
  operators: OperatoreItem[]
) => {
  const normalizedRole = normalizeRoleName(roleName);
  if (!normalizedRole) return false;

  return operators.some((item) => normalizeRoleName(item.mestiere ?? '') === normalizedRole);
};

const shouldWarnAboutMissingOperatorsForRole = ({
  roleName,
  services,
  operators,
}: {
  roleName: string;
  services: ServizioItem[];
  operators: OperatoreItem[];
}) => {
  const normalizedRole = normalizeRoleName(roleName);
  if (!normalizedRole) return false;
  if (hasConfiguredOperatorsForRole(roleName, operators)) return false;

  const distinctRoles = new Set(
    [...services.map((item) => item.mestiereRichiesto ?? ''), roleName]
      .map((item) => normalizeRoleName(item))
      .filter(Boolean)
  );

  return distinctRoles.size > 1;
};

const formatRoleLabelForDisplay = (value?: string | null) => {
  const trimmedValue = (value ?? '').trim();
  if (!trimmedValue) {
    return '';
  }

  return trimmedValue
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => {
      const lowerWord = word.toLocaleLowerCase('it-IT');
      return lowerWord.charAt(0).toLocaleUpperCase('it-IT') + lowerWord.slice(1);
    })
    .join(' ');
};

const splitServiceTitleForDisplay = (value: string) => {
  const trimmedValue = value.trim().replace(/\s+/g, ' ');
  const comboMatch = trimmedValue.match(/^(.*?)\s+(\+|&|e)\s+(.*?)$/i);

  if (comboMatch) {
    const top = comboMatch[1]?.trim() ?? '';
    const separator = comboMatch[2]?.trim() ?? '';
    const bottom = comboMatch[3]?.trim() ?? '';
    if (top && separator && bottom) {
      return {
        top,
        separator,
        bottom,
        isCombo: true,
      };
    }
  }

  const words = trimmedValue.split(/\s+/).filter(Boolean);
  // Character count alone misses visually wide names such as "Ceretta Gambe".
  const visualWeight = Array.from(trimmedValue).reduce((total, character) => {
    if (/\s/.test(character)) return total + 0.35;
    if (/[mwMWGQO]/.test(character)) return total + 1.2;
    if (/[ilIjtfr]/.test(character)) return total + 0.6;
    return total + 1;
  }, 0);

  if (words.length > 1 && (trimmedValue.length > 13 || visualWeight > 10)) {
    let bestSplitIndex = 1;
    let bestDiff = Number.POSITIVE_INFINITY;

    for (let index = 1; index < words.length; index += 1) {
      const top = words.slice(0, index).join(' ');
      const bottom = words.slice(index).join(' ');
      const diff = Math.abs(top.length - bottom.length);
      if (diff < bestDiff) {
        bestDiff = diff;
        bestSplitIndex = index;
      }
    }

    return {
      top: words.slice(0, bestSplitIndex).join(' '),
      separator: null,
      bottom: words.slice(bestSplitIndex).join(' '),
      isCombo: false,
    };
  }

  return {
    top: trimmedValue,
    separator: null,
    bottom: '',
    isCombo: false,
  };
};

const buildRoleCoverageSummary = (
  services: ServizioItem[],
  operators: OperatoreItem[]
) => {
  const activeRoles = Array.from(
    new Set(
      services
        .map((item) => normalizeRoleName(item.mestiereRichiesto ?? ''))
        .filter(Boolean)
    )
  );

  const operatorCountByRole = new Map<string, number>();
  operators.forEach((item) => {
    const normalizedRole = normalizeRoleName(item.mestiere ?? '');
    if (!normalizedRole) return;
    operatorCountByRole.set(normalizedRole, (operatorCountByRole.get(normalizedRole) ?? 0) + 1);
  });

  const coveredRoles = activeRoles.filter((role) => (operatorCountByRole.get(role) ?? 0) > 0);
  const missingRoles = activeRoles.filter((role) => (operatorCountByRole.get(role) ?? 0) === 0);
  const orphanOperatorRoles = Array.from(operatorCountByRole.keys()).filter(
    (role) => !activeRoles.includes(role)
  );

  return {
    activeRoles,
    coveredRoles,
    missingRoles,
    orphanOperatorRoles,
    operatorCountByRole,
  };
};

