function PreciseSwipeAction({
  style,
  onActivate,
  accessibilityLabel,
  children,
}: {
  style: StyleProp<ViewStyle>;
  onActivate: () => void;
  accessibilityLabel: string;
  children: React.ReactNode;
}) {
  const activatedRef = useRef(false);

  const activate = useCallback(() => {
    if (activatedRef.current) {
      return;
    }

    activatedRef.current = true;
    void haptic.medium().catch(() => null);
    onActivate();
  }, [onActivate]);

  if (!IS_ANDROID) {
    return (
      <HapticTouchable
        style={style}
        onPress={onActivate}
        hapticType={Platform.OS === 'web' ? 'light' : 'medium'}
        activeOpacity={0.9}
        hitSlop={SERVICE_COMPACT_HIT_SLOP}
        accessibilityLabel={accessibilityLabel}
        {...SERVICE_FAST_TAP_PROPS}
      >
        {children}
      </HapticTouchable>
    );
  }

  return (
    <Pressable
      style={({ pressed }) => [
        style,
        pressed && styles.androidSwipeActionPressed,
      ]}
      onTouchStart={(event) => {
        event.stopPropagation();
      }}
      onPress={activate}
      onTouchEnd={(event) => event.stopPropagation()}
      onTouchCancel={(event) => event.stopPropagation()}
      onPressOut={() => {
        setTimeout(() => {
          activatedRef.current = false;
        }, 0);
      }}
      unstable_pressDelay={0}
      hitSlop={{ top: 2, bottom: 2, left: 6, right: 6 }}
      pressRetentionOffset={{ top: 10, bottom: 10, left: 8, right: 8 }}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
      android_disableSound
    >
      {children}
    </Pressable>
  );
}

type AppOnlyFastExpansionHandle = {
  open: () => void;
  close: () => void;
};

type AppOnlyFastExpansionBoundaryProps = {
  nativeTitle?: string;
  nativeOverlays?: React.ReactNode;
  onNativeVisibilityChange?: (visible: boolean) => void;
  body?: React.ReactNode;
  bodyStyle?: React.ComponentProps<typeof Animated.View>['style'];
  webExpanded: boolean;
  nativeInitiallyExpanded?: boolean;
  onWebToggle: () => void;
  children: (expanded: boolean, toggle: () => void) => React.ReactNode;
};

/**
 * On native the expanded state lives beside the accordion body, so opening a
 * section does not force the whole Services screen (catalog, cards and swipe
 * rows included) to render again. Web deliberately keeps its existing
 * controlled path and layout.
 */
function CustomServiceEditorPopup({ children, onClose }: React.PropsWithChildren<{ onClose: () => void }>) {
  if (Platform.OS === 'web') return <ServicesWebForm bare open onClose={onClose} title="Servizi su misura">{children}</ServicesWebForm>;
  return (
    <Modal supportedOrientations={TABLET_MODAL_ORIENTATIONS} visible transparent animationType="none" onRequestClose={onClose}>
      <GestureHandlerRootView style={{ flex: 1 }}>
        <CreationSheet animatePresentation title="Servizi su misura" icon="sparkles-outline" onClose={onClose}>
          {children}
        </CreationSheet>
      </GestureHandlerRootView>
    </Modal>
  );
}

const AppOnlyFastExpansionBoundary = React.forwardRef<
  AppOnlyFastExpansionHandle,
  AppOnlyFastExpansionBoundaryProps
>(function AppOnlyFastExpansionBoundary(
  { webExpanded, onWebToggle, children, body, bodyStyle, nativeTitle, nativeOverlays, onNativeVisibilityChange, nativeInitiallyExpanded = false },
  forwardedRef,
) {
  const [nativeExpanded, setNativeExpanded] = useState(nativeInitiallyExpanded);
  const insets = useSafeAreaInsets();
  const expanded = Platform.OS === 'web' ? webExpanded : nativeExpanded;
  const close = useCallback(() => {
    Keyboard.dismiss();
    setNativeExpanded(false);
    onNativeVisibilityChange?.(false);
  }, [onNativeVisibilityChange]);

  const toggle = useCallback(() => {
    if (Platform.OS === 'web') {
      onWebToggle();
      return;
    }
    setNativeExpanded((current) => !current);
    onNativeVisibilityChange?.(!nativeExpanded);
  }, [onWebToggle, onNativeVisibilityChange, nativeExpanded]);

  React.useImperativeHandle(
    forwardedRef,
    () => ({
      open: () => {setNativeExpanded(true);onNativeVisibilityChange?.(true);},
      close: () => {
        if (Platform.OS !== 'web') {
          close();
        }
      },
    }),
    [close,onNativeVisibilityChange],
  );

  if (Platform.OS !== 'web' && nativeTitle) {
    return <>
      <HapticTouchable
        onPress={toggle}
        immediatePress
        accessibilityRole="button"
        accessibilityLabel={nativeTitle}
        style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: 12, minHeight: 54, width: '100%', paddingHorizontal: 10 }}
      >
        <Text style={{ flex: 1, textAlign: 'left', color: '#0F172A', fontSize: 18, fontWeight: '800' }}>{nativeTitle}</Text>
        <Ionicons name="add-circle" size={36} color="#1D4ED8" />
      </HapticTouchable>
      <Modal visible={nativeExpanded} supportedOrientations={TABLET_MODAL_ORIENTATIONS} animationType="fade" transparent onRequestClose={close}>
        <GestureHandlerRootView style={{ flex: 1 }}>
        <CreationSheet title={nativeTitle} icon={nativeTitle === 'Aggiungi operatore' ? 'person-add-outline' : 'cut-outline'} onClose={close}>
          {body}
        </CreationSheet>
        {nativeOverlays}
        </GestureHandlerRootView>
      </Modal>
    </>;
  }

  return <>{children(expanded, toggle)}{body !== undefined ? (
    <Animated.View
      pointerEvents={expanded ? 'auto' : 'none'}
      style={[styles.formCardBody, !expanded && styles.formCardBodyCollapsed, bodyStyle]}
    >
      {body}
    </Animated.View>
  ) : null}</>;
});

// Keep creation-tab changes local: the catalog and the rest of Services do
// not participate in switching between the two editors.
function ServiceCreationModeBoundary({ children, savedMode }: {
  savedMode?: React.MutableRefObject<'single' | 'composition'>;
  children: (mode: 'single' | 'composition', setMode: React.Dispatch<React.SetStateAction<'single' | 'composition'>>) => React.ReactNode;
}) {
  const [mode, setMode] = useState<'single' | 'composition'>(savedMode?.current ?? 'single');
  useEffect(() => { if (savedMode) savedMode.current = mode; }, [mode, savedMode]);
  return <>{children(mode, setMode)}</>;
}

