const normalizeCustomHexColor = (value: string) => {
  const compact = value.trim().replace(/^#/, '');
  if (/^[0-9a-fA-F]{3}$/.test(compact)) {
    return `#${compact
      .split('')
      .map((character) => `${character}${character}`)
      .join('')}`.toUpperCase();
  }
  if (/^[0-9a-fA-F]{6}$/.test(compact)) {
    return `#${compact.toUpperCase()}`;
  }
  return '';
};

