const isIsoDateInput = (value: string) => /^\d{4}-\d{2}-\d{2}$/.test(value.trim());

const formatIsoDateForDisplay = (value: string) => {
  if (!isIsoDateInput(value)) return value;
  const [year, month, day] = value.trim().split('-');
  return `${day}-${month}-${year}`;
};

const formatIsoDateCompactForDisplay = (value: string) => {
  if (!isIsoDateInput(value)) return value;
  const [year, month, day] = value.trim().split('-');
  return `${day}/${month}/${year.slice(-2)}`;
};

const formatIsoDateCardForDisplay = (value: string) => {
  if (!isIsoDateInput(value)) return value;
  const [, month, day] = value.trim().split('-');
  return `${day}/${month}`;
};

const formatTimeCardForDisplay = (value: string) => {
  const normalized = value.trim();
  return normalized.endsWith(':00') ? normalized.slice(0, -3) : normalized;
};

const formatServiceCardPrice = (value: number) => {
  const normalized = Number.isFinite(value) ? value : 0;
  return Number.isInteger(normalized)
    ? `€${normalized}`
    : `€${normalized.toFixed(2).replace('.', ',')}`;
};

const resolveRoleEmblemIcon = (
  roleName?: string
): React.ComponentProps<typeof Ionicons>['name'] => {
  const normalized = normalizeRoleName(roleName ?? '');
  if (/barber|barbiere/.test(normalized)) return 'cut-outline';
  if (/hair|parrucch|acconci|capell/.test(normalized)) return 'color-wand-outline';
  if (/nail|onicot|manicure|pedicure/.test(normalized)) return 'sparkles-outline';
  if (/estet|beauty|viso|make.?up/.test(normalized)) return 'flower-outline';
  if (/massagg|wellness|benessere|spa/.test(normalized)) return 'leaf-outline';
  if (/tattoo|tatu/.test(normalized)) return 'brush-outline';
  return 'diamond-outline';
};

const formatOperatorRangeForDisplay = (range: Pick<OperatorAvailabilityRangeItem, 'startDate' | 'endDate'>) =>
  `${formatIsoDateForDisplay(range.startDate)} → ${range.endDate === '9999-12-31' ? 'Senza scadenza' : formatIsoDateForDisplay(range.endDate)}`;

const normalizeOperatorAvailabilityRangesForSave = (ranges: OperatorAvailabilityRangeItem[]) => {
  const byPeriod = new Map<string, OperatorAvailabilityRangeItem>();

  ranges.forEach((range) => {
    const startDate = range.startDate.trim();
    const endDate = range.endDate.trim();
    if (!isIsoDateInput(startDate) || !isIsoDateInput(endDate) || startDate > endDate) return;

    const key = `${startDate}|${endDate}`;
    if (!byPeriod.has(key)) {
      byPeriod.set(key, {
        id: range.id?.trim() || buildUniqueEntityId('range'),
        startDate,
        endDate,
        label: range.label?.trim() || undefined,
      });
    }
  });

  return [...byPeriod.values()].sort((first, second) => {
    const startCompare = first.startDate.localeCompare(second.startDate);
    return startCompare !== 0 ? startCompare : first.endDate.localeCompare(second.endDate);
  });
};

const formatWeekdaySummary = (enabledWeekdays: number[]) => {
  const normalized = [...enabledWeekdays].sort((first, second) => first - second);

  if (normalized.length === ALL_WEEKDAY_VALUES.length) {
    return 'Tutti i giorni';
  }

  return WEEKDAY_OPTIONS.filter((item) => normalized.includes(item.value))
    .map((item) => item.label)
    .join(' · ');
};

const formatAvailabilitySummary = (operator: OperatoreItem) => {
  const enabledWeekdays = operator.availability?.enabledWeekdays ?? ALL_WEEKDAY_VALUES;
  const ranges = operator.availability?.dateRanges ?? [];
  const weekdaySummary = formatWeekdaySummary(enabledWeekdays);

  if (ranges.length === 0) {
    return weekdaySummary;
  }

  if (ranges.length === 1) {
    const [range] = ranges;
    return `${weekdaySummary} · ${formatOperatorRangeForDisplay(range)}`;
  }

  return `${weekdaySummary} · ${ranges.length} periodi`;
};

